create role authenticated nologin;create role anon nologin;
create schema auth;create schema storage;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema auth,storage to authenticated,anon;
create table public.users(id uuid primary key,auth_uid uuid,role text,status text);
create table public.workers(id uuid primary key,name text,worker_code text,status text);
create table public.allocations(worker_id uuid,site_id uuid,work_date date);
create table public.site_supervisors(site_id uuid,user_id uuid);
create function public.my_role() returns text language sql stable security definer set search_path='' as $$select role from public.users where auth_uid=auth.uid() and status='active' limit 1$$;
create function public.my_user_id() returns uuid language sql stable security definer set search_path='' as $$select id from public.users where auth_uid=auth.uid() and status='active' limit 1$$;
create function public.my_site_ids() returns setof uuid language sql stable security definer set search_path='' as $$select s.site_id from public.site_supervisors s join public.users u on u.id=s.user_id where u.auth_uid=auth.uid() and u.status='active'$$;
create table public.worker_cards(id uuid primary key default gen_random_uuid(),worker_id uuid not null references public.workers(id),category text not null default 'course',label text,image_path text not null,back_image_path text,institute text,cert_no text,issued_date date,expiry_date date,position integer not null default 0,uploaded_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.worker_certificates(id uuid primary key default gen_random_uuid(),worker_id uuid not null references public.workers(id),title text,file_path text not null,file_type text not null default 'image',uploaded_by uuid,created_at timestamptz not null default now());
create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid default gen_random_uuid(),bucket_id text,name text,owner_id text);
alter table storage.objects enable row level security;
alter table public.worker_cards enable row level security;
alter table public.worker_certificates enable row level security;
alter table public.allocations enable row level security;
create policy allocations_scope on public.allocations for select to authenticated using(public.my_role() in ('admin','general_manager','operation_manager','hr_assistant','main_sup','wshc_lead') or site_id in(select public.my_site_ids()));
create policy worker_cards_all on public.worker_cards for all to authenticated using(true) with check(true);
create policy worker_certs_all on public.worker_certificates for all to authenticated using(true) with check(true);
grant select on public.workers,public.allocations to authenticated;
grant select,insert,update,delete on storage.objects to authenticated;
grant all on public.worker_cards,public.worker_certificates to anon,authenticated;
